      "type": "dict",
      "properties": {
        "file_name": {
          "type": "string",
          "description": "The name of the file from current directory to display. No path is allowed. "
        }
      },
      "required": [
        "file_name"
      ]
    },
    "response": {
      "type": "dict",
      "properties": {
        "file_content": {
          "type": "string",
          "description": "The content of the file."
        }
      }
    }
